import json,random,sys
out=[];lines=[]
for (i,a,t,q,o,n,x,fq,fx) in B:
    r=random.Random(i);perm=list(range(len(o)));r.shuffle(perm)
    oo=[o[p] for p in perm];nn=perm.index(n)
    out.append(dict(i=i,k="c",t=t,a=a,q=q,o=[z[0] for z in oo],oe=[z[1] for z in oo],n=nn,x=x,p=None))
    lines+= [(i+"_q_lulu",fq),(i+"_e_lulu",fx)]
json.dump(out,open(sys.argv[1],'w'),ensure_ascii=False)
json.dump(lines,open(sys.argv[2],'w'),ensure_ascii=False)
print(len(out),sum(len(b) for a,b in lines))
